function report=recoverRocketTemperatureDuplicateStep(folder,failedStepFolder)
%RECOVERROCKETTEMPERATUREDUPLICATESTEP 恢复同Q33的精确重复行秩拒绝，不重做已有自由求解。
% 模块一：核对当前系统、温度行、QR坐标及完整原目标，才复用失败前保存的自由方向。
% 模块二：所有当前带内行均朝域外时，保留全行约束，只复用逐项相同条件的表示。
% 模块三：受限方向重新通过完整模型、新鲜原NS及原线搜索，不放宽任何物理护栏。
% 模块四：原失败记录不改写，另存恢复步骤；最终汇总明确包含原失败和实际恢复来源。
root=fileparts(fileparts(mfilename('fullpath')));addpath(root,fullfile(root,'internalFlow'));setupCutCellFlow;
folder=char(java.io.File(folder).getCanonicalPath());failedStepFolder=char(java.io.File(failedStepFolder).getCanonicalPath());
assert(~exist(folder,'dir'));mkdir(folder);
preparationFile=fullfile(failedStepFolder,'current','peak_system.json');p=loadRocketPeakSystem(preparationFile);
preparationSHA256=rocketStreamingFileSHA256(preparationFile);stateFile=p.sourceBinding.sourceFile;
contextFile=fullfile(failedStepFolder,'direction_context.mat');context=load(contextFile,'factor','rows','preparationSHA256');
assert(strcmp(context.preparationSHA256,preparationSHA256));factor=context.factor;
c=load(p.artifacts.cache.file,'cache');rows=selectRocketTemperatureBandRows(c.cache.Q,c.cache.baseInfo,c.cache.geometry,c.cache.gas,c.cache.scale);
assert(isequaln(rows,context.rows),'TemperatureRecovery:Rows','当前温度行与失败前绑定不符。');clear context;
a=load(p.artifacts.packed.file,'packed');m=load(p.artifacts.metric.file);rhs=m.rhs;metric=m.metric;clear m;
freeFile=fullfile(failedStepFolder,'linear_checkpoints','free_direction.mat');s=load(freeFile);freeFileSHA256=rocketStreamingFileSHA256(freeFile);
assert(strcmp(s.freeDetail.method,'complete-parent-C-fixed-primitive-penalty-augmented-patch-QR-LSQR')&&s.freeDetail.nativeIterations==128);
lift=applyRocketAugmentedPatchQR(factor,s.freeCoordinates);assert(isequaln(lift,s.free),'TemperatureRecovery:Lift','保存自由方向与当前QR坐标不符。');clear lift;
image=applyRocketPackedGraph(a.packed,s.free);weighted=applyRocketPrimitiveUpdateMetric(metric,s.free);
relative=norm(rhs-image,'fro')/norm(rhs,'fro');objective=relative^2+(factor.penaltyInOriginalResidualUnits*norm(weighted,'fro')/norm(rhs,'fro'))^2;
assert(abs(relative-s.freeDetail.relativeCResidual)<=1e-10&&abs(objective-s.freeDetail.normalizedAugmentedObjective)<=1e-10, ...
    'TemperatureRecovery:Objective','保存自由方向与当前完整C/冻结W目标不符。');clear image weighted;
t=rows.H*s.free(:);b=128*eps*full(abs(rows.H)*abs(s.free(:)));active=find(rows.temperatureBoundSigns.*t>b);
assert(isequaln(t,s.tangent)&&isequaln(b,s.bound)&&isequal(active,s.violating)&&numel(active)==size(rows.H,1), ...
    'TemperatureRecovery:Active','恢复入口仅接受当前全部带内行均朝域外的已保存失败。');
selected=rows;selected.H=rows.H(active,:);selected.faceIDs=rows.faceIDs(active);
projector=buildRocketTemperatureProjector(factor,selected);
assert(projector.independentConstraintCount<projector.constraintCount&&projector.allOriginalRowsExactlyRepresented&&~projector.rankTruncationUsed);
[value,detail,coordinates]=solveRocketTemperatureProjectedDirection(a.packed,factor,rhs,metric,projector,selected,128);clear a;
tangent=rows.H*value(:);bound=128*eps*full(abs(rows.H)*abs(value(:)));violating=find(rows.temperatureBoundSigns.*tangent>bound);
assert(isempty(violating),'TemperatureRecovery:Feasible','保留全部原行的当前方向未通过算术可行性检查。');
freeReplay=struct('file',freeFile,'sha256',freeFileSHA256,'currentPreparationSHA256',preparationSHA256, ...
    'coordinatesLiftExactlyVerified',true,'currentOriginalCResidual',relative,'currentAugmentedObjective',objective, ...
    'allCurrentRowsAndSignsExactlyVerified',true,'reusedNativeIterations',s.freeDetail.nativeIterations, ...
    'newNativeIterations',detail.nativeIterations,'newActualNSEvaluations',0);
item=struct('activeRowIndices',active,'activeFaceIDs',rows.faceIDs(active),'newRowIndices',active, ...
    'projector',projector,'value',value,'detail',detail,'coordinates',coordinates, ...
    'temperatureDerivativeK',tangent,'localDotRoundoffBoundK',bound,'remainingViolatingRowIndices',violating);
evidence=struct('free',s.free,'freeDetail',s.freeDetail,'freeCoordinates',s.freeCoordinates,'cycles',{{item}}, ...
    'selectedCoordinates',coordinates,'selectedDetail',detail,'rows',rows,'freeCheckpointReplay',freeReplay);
directionReport=struct('method','current-temperature-band-add-only-feasible-direction-QR-LSQR-prototype', ...
    'options',struct('maximumIterations',128,'maximumActiveSolves',3),'freeLinearReport',s.freeDetail, ...
    'linearReport',detail,'activeSolveCount',1,'totalNativeIterations',s.freeDetail.nativeIterations+detail.nativeIterations, ...
    'activeRowIndices',active,'activeFaceIDs',rows.faceIDs(active),'bandFaceIDs',rows.faceIDs, ...
    'temperatureBoundSigns',rows.temperatureBoundSigns,'temperatureDerivativeK',tangent, ...
    'localDotRoundoffBoundK',bound,'remainingViolatingRowIndices',violating,'bandDirectionFeasible',true, ...
    'stopReason','current-band-direction-feasible','oldActiveSetInherited',false,'coolingRowsMayRemainFree',true, ...
    'constrainedOptimumClaimed',false,'nonlinearTemperatureBoundGuaranteed',false,'physicalBoundaryConditionAdded',false, ...
    'newActualNSEvaluations',0,'newProductionSolvedAreaM2',0,'physicalSolution',false, ...
    'freeCheckpointReplay',freeReplay,'newNativeIterations',detail.nativeIterations, ...
    'reusedFreeNativeIterations',s.freeDetail.nativeIterations,'allOriginalConstraintRowsRetained',true);clear s;
sourceBinding=p.sourceBinding;sourceIdentity=p.sourceIdentity;geometryBinding=p.geometryBinding;
save(fullfile(folder,'direction_context.mat'),'factor','rows','p','preparationFile','preparationSHA256','-v7');clear factor;
save(fullfile(folder,'active_direction.mat'),'value','directionReport','evidence','rhs','metric','rows', ...
    'sourceBinding','sourceIdentity','geometryBinding','preparationFile','preparationSHA256','-v7');clear evidence;
[model,modelDetail]=applyCutCellSelectedDirection(c.cache,value);clear c;
defect=norm(rhs+model,'fro')/norm(rhs,'fro');assert(defect<=.1,'TemperatureRecovery:Model','完整原模型未过原0.1门槛。');
row=struct('step',3,'sourceBinding',sourceBinding,'preparationFile',preparationFile,'preparationSHA256',preparationSHA256, ...
    'directionFile',fullfile(folder,'active_direction.mat'),'directionFileSHA256',rocketStreamingFileSHA256(fullfile(folder,'active_direction.mat')), ...
    'directionReport',directionReport,'completeSelectedModelRelativeDefect',defect, ...
    'newPreparationActualNS',1,'newPreparationActualNSInRecovery',0,'preparationFromInitialFailedAttempt',true, ...
    'probe',[],'main',[],'resultFolder','','newProbeActualNS',0,'newMainActualNS',0,'stopReason','fresh-original-NS-direction-gate', ...
    'physicalSolution',false,'newProductionSolvedAreaM2',0);
save(fullfile(folder,'active_model.mat'),'value','model','modelDetail','row','-v7');
row.probe=createRocketNSDirectionProbe(fullfile(folder,'probe'),stateFile,p.geometryBinding.file,p.geometryBinding.variable,value,'result');
row.newProbeActualNS=row.probe.newActualNSEvaluations;
if row.probe.originalNSDirectionTargetMet
    options=struct('linearEquation','steady-newton','normalEulerLinearization','exact-branch','jacobianAction','original-difference', ...
        'maximumIterations',1,'initialPseudoDt',1e-7,'maximumKrylovIterations',48,'linearRelativeTolerance',.1, ...
        'maximumStepRetries',0,'maximumLineSearch',16,'steadyInitialGuess', ...
        struct('file',fullfile(folder,'probe','direct_ns_direction_probe.mat'),'variant','ns-probe','scale',1));
    row.resultFolder=fullfile(folder,'krylov01');row.main=continueRocketWallVelocityKrylov(row.resultFolder,fileparts(stateFile),options);
    row.newMainActualNS=row.main.residualEvaluations;row.stopReason=row.main.stopReason;
end
fid=fopen(fullfile(folder,'step.json'),'w','n','UTF-8');fprintf(fid,'%s',jsonencode(row));fclose(fid);
phase=fileparts(failedStepFolder);progressFile=fullfile(phase,'progress.json');previous=jsondecode(fileread(progressFile));
assert(numel(previous)==2&&strcmp(previous(2).resultFolder,fileparts(stateFile)));
steps=num2cell(previous);steps{end+1}=row;lastAcceptedFolder=fileparts(stateFile);
if ~isempty(row.main)&&row.main.acceptedNonlinearIterations>0,lastAcceptedFolder=row.resultFolder;end
failureFile=fullfile(root,'outputs/v83_validation/activefull88_process.json');failure=jsondecode(fileread(failureFile));assert(failure.exitCode==1);
report=struct('status','tested-current-temperature-study-with-explicit-exact-duplicate-third-step-recovery', ...
    'initialStateFile',previous(1).sourceBinding.sourceFile,'maximumSteps',3,'steps',{steps}, ...
    'lastAcceptedFolder',lastAcceptedFolder,'sameEquationHistoryContinued',true,'oldActiveSetsInherited',false, ...
    'recovery',struct('originalFailureFile',failureFile,'originalFailureSHA256',rocketStreamingFileSHA256(failureFile), ...
        'originalFailureExitCode',1,'originalTwoStepProgressFile',progressFile,'originalTwoStepProgressSHA256',rocketStreamingFileSHA256(progressFile), ...
        'recoveryFolder',folder,'allOriginalConstraintRowsRetained',true,'freeCheckpointReplay',freeReplay), ...
    'physicalSolution',false,'newProductionSolvedAreaM2',0);
target=fullfile(phase,'active_continuation.json');assert(~isfile(target));
fid=fopen(target,'w','n','UTF-8');fprintf(fid,'%s',jsonencode(report));fclose(fid);disp(report);
end
